"""Freeze complete East run cycle at selected anatomical and material scale."""
from pathlib import Path
import hashlib,json
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'character/marsh-east-run-material-v1/sources'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    guide=json.loads((BASE/'guide-provenance.json').read_text())
    for r in guide['primarySourceFrames']+guide['guideSourceFrames']:assert sha(ROOT/r['path'])==r['sha256']
    prompt='''Create a transparent pixel-art SOURCE SHEET of SEVEN COMPLETE full-body Marsh figures in one horizontal row, with generous transparent gutters. All seven face EAST, toward the RIGHT edge, in the SAME elevated side camera as reference1. Reference1 selected East idle/walk is PRIMARY for exact fitted adult head/torso/limb/equipment proportions, camera, drawing density and warm matte ivory/sage/slate materials. Reference2 existing East run is ONLY for running attitude and complete connected motion: its broader head/upper body must not become anatomical authority. Reference3 original EAST standing master supplies adult blond male facial identity, nose/chin profile, swept hair, small visible metal plate on HIS RIGHT temple, harness/chest equipment and fitted suit details. Never mirror West or turn front; do not copy magenta background.

Figures1-6 are a coherent SIX-PHASE rightward running cycle, each100ms, alternating near and far legs through contact/passing/flight. NEAR means the leg closer to camera; FAR means the other leg. 1 NEAR leg reaches FORWARD/RIGHT and DOWN to initial boot contact, FAR leg trails folded behind/LEFT; FAR arm swings forward, NEAR arm back. 2 support compresses gently over NEAR planted foot, FAR knee passes under pelvis, arms pass near neutral. 3 FAR knee lifts forward/RIGHT into flight, NEAR leg sweeps back/LEFT with heel raised; NEAR arm swings forward, FAR arm back. 4 FAR leg reaches forward/RIGHT and DOWN to contact, NEAR leg folded behind/LEFT; NEAR arm forward, FAR arm back. 5 support compresses gently over FAR foot, NEAR knee passes under pelvis, arms pass near neutral. 6 NEAR knee lifts forward/RIGHT into flight, FAR leg sweeps back/LEFT with raised heel; FAR arm forward, NEAR arm back. Then wrap naturally to1. Distinct connected shoulder/elbow/hand and hip/knee/ankle/boot progression; no repeated identical half-stride, fused legs, disconnected hands, extra limbs or backwards knee joints. Modest forward running lean, compact arm pump, natural mild body bounce. Both complete feet lift in flight3/6; contacts1/4 and supports2/5 keep the planted sole at shared floor level. Do not draw six repeated leap poses.

Figure7 stands neutral arms down exactly as selected East idle, facing RIGHT, a ruler at the SAME drawing scale as the running figures. Selected neutral occupies32wide by147high native pixels,184canvas,pivot92/172,declaredstandingHeight148; these numbers describe calibration, not text. ONE common anatomical scale from this neutral; do not resize each running pose to147high, widen profile torso, enlarge head/collar or equalize articulated leg-spread width to32. Preserve adult head/chest-equipment/thigh/boot sizes through bending and foreshortening. Warm ivory BOOT UPPERS/guards with matte charcoal SOLES, charcoal gloves, slate flexible joints, sage shoulders/pouches, ivory fabric/panels. Restrained warm crisp pixel clusters and matte grade consistent throughout. No cyan/coldblue, glossy highlights, broad new outlines, helmet, backpack, weapon, tools or effects. Actual transparent background directly outside complete silhouettes, no halo, haze, glow, floor, shadows, labels, text or magenta. Seven COMPLETE whole bodies, no anatomy patches, limb pieces, mirroring or recolouring.'''
    path=BASE/'run-01.prompt.txt';assert not path.exists();path.write_text(prompt+'\n',encoding='utf-8')
    refs=[BASE/'selected-east-idle-gait.png',BASE/'run-pose-guide.png',ROOT/'character/marsh-motion-polish-v1/sources/east-standing-identity-01.png']
    req={'normalAdmission':False,'status':'frozen exact whole East cycle request before generation','promptSha256':sha(path),'orderedReferences':[{'path':p.relative_to(ROOT).as_posix(),'sha256':sha(p)} for p in refs],'guideProvenance':guide,'transparentBackground':True,'sheetGrid':[7,1],'contract':{'canvas':[184,184],'pivot':[92,172],'standingHeight':148,'durationsMs':[100]*6,'loop':True,'strideDistanceCells':.11027027027027027},'constraints':'Complete East/right figures; one selected147-occupied neutral scale. No mirror, patch, recolour or per-pose fit.'}
    (BASE/'run-01.request.json').write_text(json.dumps(req,indent=2)+'\n');print('Frozen exact seven-complete-figure East request and three ordered reference SHAs.')
if __name__=='__main__':main()
